{
  "name": "http-status-server",
  "version": "1.0.0",
  "description": "Node.js HTTP server with standard status code reason phrases",
  "type": "module",
  "main": "src/status-codes.js",
  "scripts": {
    "start": "node src/server.js",
    "test": "node --test"
  },
  "engines": {
    "node": ">=18"
  },
  "license": "MIT"
}

import { STATUS_CODES } from "node:http";

export const statusCodes = STATUS_CODES;

export function reasonPhrase(code, fallback = "Unknown") {
  return statusCodes[code] ?? fallback;
}

import http from "node:http";
import { reasonPhrase, statusCodes } from "./status-codes.js";

const port = Number(process.env.PORT ?? 3000);

const server = http.createServer((req, res) => {
  if (req.url === "/status-codes") {
    res.writeHead(200, { "content-type": "application/json" });
    res.end(JSON.stringify(statusCodes));
    return;
  }

  const code = 200;
  res.writeHead(code, { "content-type": "text/plain" });
  res.end(`${code} ${reasonPhrase(code)}\n`);
});

server.listen(port, () => {
  console.log(`Listening on http://localhost:${port}`);
});

import assert from "node:assert/strict";
import test from "node:test";
import { reasonPhrase, statusCodes } from "../src/status-codes.js";

test("looks up standard reason phrases", () => {
  assert.equal(reasonPhrase(200), "OK");
  assert.equal(reasonPhrase(404), "Not Found");
  assert.equal(reasonPhrase(500), "Internal Server Error");
});

test("falls back for unknown codes", () => {
  assert.equal(reasonPhrase(599), "Unknown");
  assert.equal(reasonPhrase(599, "Custom"), "Custom");
});

test("table covers common codes", () => {
  for (const code of [200, 201, 204, 301, 400, 401, 403, 404, 500, 503]) {
    assert.ok(typeof statusCodes[code] === "string");
  }
});
